questionvariables.text:
correct_answer:rand_selection([
[1, true, "Used in controlling Births in a nation.
"],
[2, true, "Used in shaping the direction of politics in a nation.
"],
[3, true, "Used for doing mass vaccination.
"]],1);
incorrect_answers:rand_selection([
[4, false, "Use by individuals in recording births, deaths, marriages and divorce."],
[5, false, "Used by Government agencies for a variety of administrative purposes."],
[6, false, "Vital statistics are indispensable in demographic research."],
[7, false, "Used in public administration"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
